func (s *UnlinkedAccount) GetLinkedAccountNumber() OptString {
	return s.LinkedAccountNumber
}

// SetAccountEmail sets the value of AccountEmail.
func (s *UnlinkedAccount) SetAccountEmail(val OptString) {
	s.AccountEmail = val
}

// SetAccountName sets the value of AccountName.
func (s *UnlinkedAccount) SetAccountName(val OptString) {
	s.AccountName = val
}

