func (s *UnlinkedAccount) SetAccountNumber(val OptString) {
	s.AccountNumber = val
}

// SetLinkedAccountNumber sets the value of LinkedAccountNumber.
func (s *UnlinkedAccount) SetLinkedAccountNumber(val OptString) {
	s.LinkedAccountNumber = val
}

